fun FlowContent.orderForm(invalid: Boolean = false) {
    val field = no.lotek.Lt.field(id = "$codename$", required = no.lotek.RequiredMarker.SYMBOL, error = true, invalid = invalid)
    form {
        id = "$order_form$"
        attributes["novalidate"] = ""
        label { lt(field.label); +"Codename" }
        input { lt(no.lotek.Lt.input(type = no.lotek.InputType.TEXT), field.control); name = "$codename$"; required = true }
        p { lt(no.lotek.Lt.errorText(), field.error); +"Enter a codename." }
        button { lt(no.lotek.Lt.button()); type = ButtonType.submit; +"Order the job" }
    }
}

data class Part(val key: String, val title: String, val text: String)

fun FlowContent.claimTabs(
    parts: List<Part> = listOf(
        Part("claim", "Claim", "Claim AV-2079-0481 was filed on 4 March 2079."),
        Part("attachments", "Attachments", "Three attachments have been uploaded."),
    ),
) {
    val tabs = no.lotek.Lt.tabs(id = "$claim_tabs$", keys = parts.map { it.key }, label = "Parts of the claim")
    ltTabs {
        id = "$claim_tabs$"
        ul {
            lt(tabs.list)
            parts.zip(tabs.tabs).forEach { (part, tab) -> li { a { lt(tab); +part.title } } }
        }
        for ((i, part) in parts.withIndex()) {
            section {
                lt(tabs.panels[i])
                h2 { lt(tabs.headings[i]); +part.title }
                p { +part.text }
            }
        }
    }
    script(type = "module") {
        unsafe {
            +"""
            document.getElementById("$claim_tabs$").addEventListener("tab-select", (evt) => {
              console.log("selected tab", evt.detail.index)
            })
            """
        }
    }
}

data class Fault(val field: String, val message: String)

fun FlowContent.orderForm(faults: List<Fault> = emptyList()) {
    val summary = no.lotek.Lt.errorSummary(count = faults.size, id = "$errors$", titleId = "$errors_title$")
    val fixer = no.lotek.Lt.field(id = "$fixer$", invalid = faults.any { it.field == "$fixer$" })
    form {
        attributes["novalidate"] = ""
        ltErrorSummary {
            lt(summary.host)
            h2 {
                lt(summary.title)
                if (faults.isNotEmpty()) +(if (faults.size == 1) "The form has one error" else "The form has $${faults.size} errors")
            }
            ul {
                lt(no.lotek.Lt.list())
                for (fault in faults) li { a(href = "#$${fault.field}") { +fault.message } }
            }
        }
        label { lt(fixer.label); +"Fixer's address" }
        input { lt(no.lotek.Lt.input(type = no.lotek.InputType.EMAIL), fixer.control); name = "$fixer$" }
        button { lt(no.lotek.Lt.button()); +"Order the job" }
    }
    script(type = "module") {
        unsafe {
            +"""
            const box = document.getElementById("$errors$")

            function showErrors(errors) {
              box.querySelector("ul").innerHTML = errors
                .map((e) => `<li><a href="#$${'$$'}{e.id}">$${'$$'}{e.message}</a></li>`)
                .join("")

              // The heading and hidden are written here, as a server would.
              if (errors.length > 0) {
                box.querySelector("h2").textContent =
                  errors.length === 1 ? "The form has one error" : `The form has $${'$$'}{errors.length} errors`
              }
              // Hidden and shown again, so focus also moves when the form fails
              // again while the box is already visible.
              box.hidden = true
              box.hidden = errors.length === 0
            }

            const fixer = document.getElementById("$fixer$")

            document.querySelector("form").addEventListener("submit", (event) => {
              event.preventDefault()

              const errors = fixer.value.includes("@")
                ? []
                : [{ id: "$fixer$", message: "Enter the fixer's address with an @" }]

              showErrors(errors)
            })
            """
        }
    }
}

fun FlowContent.actionsMenu() {
    val menu = no.lotek.Lt.popover(id = "$actions$", placement = no.lotek.PopoverPlacement.BOTTOM_END)
    ltPopover {
        id = "$menu$"
        lt(menu.host)
        button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY), menu.trigger); type = ButtonType.button; +"Actions" }
        ul {
            lt(menu.panel)
            li { button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.GHOST)); type = ButtonType.button; +"Mark LDG-117 returned" } }
            li { button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.GHOST)); type = ButtonType.button; +"Charge the late fee" } }
        }
    }
    script(type = "module") {
        unsafe {
            +"""
            const menu = document.getElementById("$menu$")
            const panel = menu.querySelector(".lt-popover")

            // Close the menu when an action has been chosen
            menu.addEventListener("click", (event) => {
              if (panel.contains(event.target) && event.target.closest("button")) menu.hide()
            })
            """
        }
    }
}

data class Breaker(val code: String, val name: String)

fun FlowContent.breakerSearch(
    breakers: List<Breaker> = listOf(Breaker("crowbar", "Crowbar"), Breaker("needle", "Needle")),
) {
    val search = no.lotek.Lt.suggestion(id = "$breaker$", keys = breakers.map { it.code })
    ltSuggestion {
        id = "$breaker_search$"
        label { lt(search.label); +"Breaker" }
        input { lt(search.control); name = "$breaker$" }
        ul {
            lt(search.list)
            breakers.zip(search.options).forEach { (breaker, option) -> li { lt(option); +breaker.name } }
        }
        p { lt(search.empty); +"No matches" }
        span { lt(search.status) }
    }
    script(type = "module") {
        unsafe {
            +"""
            document.getElementById("$breaker_search$").addEventListener("suggestion-select", (evt) => {
              console.log("selected", evt.detail.label, evt.detail.value)
            })
            """
        }
    }
}

fun FlowContent.cancelJob() {
    val box = no.lotek.Lt.dialog(titleId = "$confirm_title$")
    button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.DANGER)); id = "$open_confirm$"; type = ButtonType.button; +"Cancel the job" }
    dialog {
        lt(box.dialog)
        id = "$confirm$"
        h2 { lt(box.title); +"Cancel job 222-0481?" }
        div {
            lt(box.body)
            p { +"The crew keeps the advance. This cannot be undone." }
        }
        form {
            lt(box.footer)
            attributes["method"] = "dialog"
            button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY)); value = "keep"; +"Keep the job" }
            button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.DANGER)); value = "cancel"; +"Cancel the job" }
        }
    }
    script(type = "module") {
        unsafe {
            +"""
            const dialog = document.getElementById("$confirm$")

            document.getElementById("$open_confirm$").addEventListener("click", () => {
              // Escape and close() without a value leave the previous value in place.
              dialog.returnValue = ""
              dialog.showModal()
            })

            dialog.addEventListener("close", () => {
              if (dialog.returnValue === "cancel") {
                // Cancel the job here
              }
            })
            """
        }
    }
}

fun FlowContent.relay() {
    ltToast { lt(no.lotek.Lt.toast(label = "Messages").host); id = "$messages$" }
    button { lt(no.lotek.Lt.button()); id = "$restart$"; type = ButtonType.button; +"Restart relay 14" }
    script(type = "module") {
        unsafe {
            +"""
            const messages = document.getElementById("$messages$")

            document.getElementById("$restart$").addEventListener("click", async () => {
              try {
                await restartRelay(14)
                messages.show("Relay 14 is back", { color: "success" })
              } catch {
                messages.show("Relay 14 did not answer. Try again.", { color: "danger", duration: 0 })
              }
            })
            """
        }
    }
}

fun FlowContent.sessionWarning() {
    val session = no.lotek.Lt.sessionTimeout(titleId = "$session_title$", warnAt = 1500, expiresAt = 1800)
    ltSessionTimeout {
        lt(session.host)
        dialog {
            lt(session.dialog)
            h2 { lt(session.title); +"Your session is ending" }
            p {
                lt(session.text)
                +"Your session on the Lattice ends in "
                span { lt(session.count) }
                +". Unsaved routes will be lost."
            }
            span { lt(session.live) }
            form {
                lt(session.actions)
                attributes["method"] = "dialog"
                button { lt(no.lotek.Lt.button(), session.extend); +"Stay connected" }
                button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY), session.logout); +"Log out" }
            }
        }
    }
    script(type = "module") {
        unsafe {
            +"""
            const session = document.querySelector("lt-session-timeout")

            session.addEventListener("session-extend", async () => {
              await fetch("/api/extend-session", { method: "POST" })
            })

            session.addEventListener("session-expired", () => {
              location.href = "/log-in?reason=expired"
            })
            """
        }
    }
}

fun FlowContent.connection() {
    ltConnectionStatus { lt(no.lotek.Lt.connectionStatus()) }
    // The bar shows by itself when the browser goes offline. That the
    // server stopped answering, only the app knows, and says so here.
    script(type = "module") {
        unsafe {
            +"""
            import { reportFailure, reportSuccess } from
              "$${no.lotek.LotekWebJar.ROOT}/dist/components/standalone/connection-status/lt-connection-status.js"

            const connection = document.querySelector("lt-connection-status")
            if (!connection) throw new Error("element not found")

            // A module keeps its names to itself, so the function the app saves through
            // is put on window, where its other scripts call it:
            //   form.addEventListener("submit", (event) => {
            //     event.preventDefault()
            //     saveRoute(new FormData(form))
            //   })
            // Any answer means the server is there, an error status included; only a
            // request that got no answer is a lost connection. reportSuccess and
            // reportFailure wait for the component to be registered, and warn when it
            // never is; the save itself never waits.
            window.saveRoute = async (body) => {
              let response
              try {
                response = await fetch("/api/routes", { method: "POST", body })
              } catch {}
              if (response) await reportSuccess(connection)
              else await reportFailure(connection)
              return response
            }
            """
        }
    }
}
